const DAY_MS = 24 * 60 * 60 * 1000;
const TEN_MINUTES_MS = 10 * 60 * 1000;
const GOOD_INTERVALS = Object.freeze([2, 7, 30, 90, 180, 365]);

export const RATINGS = Object.freeze(["again", "hard", "good", "easy"]);

function asDate(value) {
  const date = value instanceof Date ? new Date(value) : new Date(value);
  if (Number.isNaN(date.getTime())) throw new Error("Invalid date");
  return date;
}

function addMilliseconds(date, milliseconds) {
  return new Date(date.getTime() + milliseconds);
}

function intervalForStage(stage) {
  return GOOD_INTERVALS[Math.min(Math.max(stage - 1, 0), GOOD_INTERVALS.length - 1)];
}

export function scheduleReview(previous, rating, reviewedAt = new Date()) {
  if (!RATINGS.includes(rating)) {
    throw new Error(`Rating must be one of: ${RATINGS.join(", ")}`);
  }

  const now = asDate(reviewedAt);
  const oldStage = Number.isInteger(previous?.stage) ? previous.stage : 0;
  let stage = oldStage;
  let intervalDays = 0;
  let due;

  if (rating === "again") {
    stage = Math.max(0, oldStage - 1);
    due = addMilliseconds(now, TEN_MINUTES_MS);
  } else if (rating === "hard") {
    stage = Math.max(1, oldStage);
    intervalDays = Math.max(1, Math.round(intervalForStage(stage) / 2));
    due = addMilliseconds(now, intervalDays * DAY_MS);
  } else if (rating === "good") {
    stage = Math.min(oldStage + 1, GOOD_INTERVALS.length);
    intervalDays = intervalForStage(stage);
    due = addMilliseconds(now, intervalDays * DAY_MS);
  } else {
    stage = Math.min(oldStage + 2, GOOD_INTERVALS.length);
    intervalDays = intervalForStage(stage);
    due = addMilliseconds(now, intervalDays * DAY_MS);
  }

  return {
    stage,
    intervalDays,
    due: due.toISOString(),
    lastReviewed: now.toISOString(),
    lastRating: rating,
    reviews: (previous?.reviews ?? 0) + 1,
    lapses: (previous?.lapses ?? 0) + (rating === "again" ? 1 : 0),
  };
}

export function dueCards(cards, reviews = {}, now = new Date()) {
  const timestamp = asDate(now).getTime();
  return cards.filter(card => {
    const record = reviews[card.id];
    return !record?.due || new Date(record.due).getTime() <= timestamp;
  });
}

export function summarizeDeck(cards, reviews = {}, now = new Date()) {
  const due = dueCards(cards, reviews, now).length;
  const reviewedIds = new Set(Object.keys(reviews));
  const learned = cards.filter(card => (reviews[card.id]?.stage ?? 0) >= 3).length;
  const lapses = Object.values(reviews).reduce(
    (total, record) => total + (record.lapses ?? 0),
    0,
  );

  return {
    total: cards.length,
    due,
    unseen: cards.filter(card => !reviewedIds.has(card.id)).length,
    reviewed: cards.filter(card => reviewedIds.has(card.id)).length,
    learned,
    lapses,
  };
}
